WITH DADOS_YTD AS (    SELECT        CTACTB,        SUM(CASE             WHEN YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE))            THEN VLRLANC ELSE 0         END) AS VALOR_ATUAL,        SUM(CASE             WHEN YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR))            THEN VLRLANC ELSE 0         END) AS VALOR_ANTERIOR    FROM IMP_BASE_BALANCETE    WHERE CODEMP = :VAR_EMPRESA_DRE      AND (CTACTB LIKE '3%' OR CTACTB LIKE '4%' OR CTACTB LIKE '5%')      AND (            YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE))            OR            YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR))      )    GROUP BY CTACTB),regras_contas AS (    SELECT DISTINCT        DET.ORDEM,        DET.NOME_GRUPO,        DET.COD_NOTA_EXPLICATIVA,        DETCTACTB.PADRAO_CTACTB,        DETCTACTB.SINAL    FROM ESTR_DEMONSTRATIVOS EST    INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_REFERENCIA DETREF ON DET.ID = DETREF.ID_DET_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_CTACTB DETCTACTB ON DETREF.ID = DETCTACTB.ID_DET_DEMONSTRATIVO_REFERENCIA    WHERE EST.ID = 3      AND DETREF.ANO_REFERENCIA = (          SELECT MAX(R.ANO_REFERENCIA)          FROM DET_DEMONSTRATIVO_REFERENCIA R          WHERE R.ID_DET_DEMONSTRATIVO = DET.ID            AND R.ANO_REFERENCIA <= YEAR(DATE(:VAR_DATA_REF_DRE))      )),regras_excluidas AS (    SELECT DISTINCT        DETCTACTB_EXC.PADRAO_CTACTB    FROM ESTR_DEMONSTRATIVOS EST    INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_REFERENCIA DETREF ON DET.ID = DETREF.ID_DET_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_CTACTB_EXC DETCTACTB_EXC ON DETREF.ID = DETCTACTB_EXC.ID_DET_DEMONSTRATIVO_REFERENCIA    WHERE EST.ID = 3      AND DETREF.ANO_REFERENCIA = (          SELECT MAX(R.ANO_REFERENCIA)          FROM DET_DEMONSTRATIVO_REFERENCIA R          WHERE R.ID_DET_DEMONSTRATIVO = DET.ID            AND R.ANO_REFERENCIA <= YEAR(DATE(:VAR_DATA_REF_DRE))      )),contas_mapeadas AS (    SELECT        D.VALOR_ATUAL,        D.VALOR_ANTERIOR,        R.ORDEM,        R.NOME_GRUPO,        R.COD_NOTA_EXPLICATIVA,        R.SINAL,        ROW_NUMBER() OVER(PARTITION BY D.CTACTB ORDER BY LENGTH(R.PADRAO_CTACTB) DESC) as rn    FROM DADOS_YTD D    JOIN regras_contas R ON D.CTACTB LIKE R.PADRAO_CTACTB    LEFT JOIN regras_excluidas E ON D.CTACTB LIKE E.PADRAO_CTACTB    WHERE E.PADRAO_CTACTB IS NULL)SELECT    R.ORDEM AS HIERARQUIA,    R.NOME_GRUPO AS DESCRICAO,    R.COD_NOTA_EXPLICATIVA AS NOTA,    IFNULL(Agg.VALOR_ANO_ATUAL, 0) AS VALOR_ANO_ATUAL,    IFNULL(Agg.VALOR_ANO_ANTERIOR, 0) AS VALOR_ANO_ANTERIORFROM (    SELECT DISTINCT ORDEM, NOME_GRUPO, COD_NOTA_EXPLICATIVA FROM regras_contas) RLEFT JOIN (    SELECT        M.ORDEM,        M.NOME_GRUPO,        M.COD_NOTA_EXPLICATIVA,        SUM(IFNULL(M.VALOR_ATUAL, 0) * M.SINAL) AS VALOR_ANO_ATUAL,        SUM(IFNULL(M.VALOR_ANTERIOR, 0) * M.SINAL) AS VALOR_ANO_ANTERIOR    FROM contas_mapeadas M    WHERE M.rn = 1    GROUP BY M.ORDEM, M.NOME_GRUPO, M.COD_NOTA_EXPLICATIVA) Agg ON R.ORDEM = Agg.ORDEM AND R.NOME_GRUPO = Agg.NOME_GRUPOORDER BY R.ORDEM